session_start();header('Content-Type: text/html; charset=utf-8');if(empty($_SESSION['usuario_id'])){http_response_code(401);exit('Inicia sesión para subir el comprobante.');}require_once __DIR__.'/conexion.php';$id=(int)($_POST['pedido_id']??0);$q=$pdo->prepare('SELECT id FROM pedidos WHERE id=? AND usuario_id=?');$q->execute([$id,$_SESSION['usuario_id']]);if(!$q->fetch()){http_response_code(404);exit('Pedido no encontrado.');}if(empty($_FILES['comprobante'])||$_FILES['comprobante']['error']!==UPLOAD_ERR_OK||$_FILES['comprobante']['size']>5*1024*1024)exit('Archivo inválido o mayor a 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['comprobante']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))exit('Formato no permitido.');$dir=dirname(__DIR__).'/uploads/comprobantes/';if(!is_dir($dir))mkdir($dir,0755,true);$name='pago_'.$id.'_'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file($_FILES['comprobante']['tmp_name'],$dir.$name))exit('No se pudo guardar el archivo.');$path='uploads/comprobantes/'.$name;$u=$pdo->prepare('UPDATE pedidos SET comprobante_pago=?,pago_verificado=0,pago_verificado_en=NULL WHERE id=?');$u->execute([$path,$id]);header('Location: ../perfil.php?comprobante=ok');
